// ================= EDIT THESE SETTINGS =================
const config = {
  businessName: 'Your HVAC Company',
  timezone: 'America/New_York',
  voice: 'Polly.Joanna-Neural',          // Twilio text-to-speech voice
  language: 'en-US',
  // Who the AI can transfer callers to. Every number in a list rings at once; first to answer gets the call.
  departments: {
    service: { label: 'service, repairs and scheduling', numbers: ['+15555550100'] },
    sales:   { label: 'sales, quotes and new installations', numbers: ['+15555550101'] },
    billing: { label: 'billing, invoices and payments', numbers: ['+15555550102'] },
    manager: { label: 'a manager, for complaints or escalations', numbers: ['+15555550103'] },
  },
  defaultDepartment: 'service',
  whisperToStaff: true,                  // staff hear who is calling and why before being connected
  emergencyNumbers: ['+15555550199'],    // on-call emergency tech(s)
  staffSmsNumber: '+15555550100',        // receives staff SMS alerts
  sheetId: 'YOUR_GOOGLE_SHEET_ID',       // Google Sheets CRM file ID
  callbackMinutes: 15,
  smsEveryCallSummary: true,             // SMS staff a summary when the AI ends a call
  speechHints: 'furnace, AC, air conditioner, heat pump, thermostat, carbon monoxide, gas leak, appointment, maintenance, tune-up, ductwork',
};
// =======================================================

const req = $input.first().json;
const body = req.body || {};
const query = req.query || {};
const speech = String(body.SpeechResult || '').trim();

// Emergency check: runs on every caller sentence, before the AI.
const emergencyPatterns = [
  { type: 'Gas leak', re: /\b(gas (smell|leak)|smell(s|ing)? (of |like )?gas|rotten eggs?)\b/i },
  { type: 'Carbon monoxide', re: /\b(carbon monoxide|monoxide|co (alarm|detector))\b/i },
  { type: 'Fire / smoke', re: /\b(on fire|fire in|smoke|smoking|flames?|sparks?|sparking|burning smell|smells? (like )?burning)\b/i },
  { type: 'Electrical hazard', re: /\b(exposed wires?|electrical (fire|burning)|got shocked|electrocut\w*)\b/i },
  { type: 'Flooding', re: /\b(flood(ing|ed)?|water everywhere|burst pipe)\b/i },
  { type: 'Emergency', re: /\b(emergency|nine one one|911)\b/i },
];
const hit = speech ? emergencyPatterns.find((p) => p.re.test(speech)) : null;

return [{
  json: {
    config,
    stage: query.stage || 'incoming',
    reason: query.reason || '',
    callSid: body.CallSid || '',
    from: body.From || '',
    to: body.To || '',
    speech,
    confidence: Number(body.Confidence || 0),
    callStatus: body.CallStatus || '',
    duration: Number(body.CallDuration || 0),
    dialStatus: body.DialCallStatus || '',
    isEmergency: Boolean(hit),
    emergencyType: hit ? hit.type : '',
    timestamp: $now.setZone(config.timezone).toFormat('yyyy-LL-dd HH:mm:ss'),
  },
}];

const call = $input.first().json;
const c = call.config;
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
const say = (t) => `<Say voice="${c.voice}" language="${c.language}">${esc(t)}</Say>`;
// Relative URLs are resolved by Twilio against this webhook's URL.
const gather = (prompt) =>
  `<Gather input="speech" action="hvac-voice?stage=turn" method="POST" speechTimeout="auto" ` +
  `speechModel="phone_call" language="${c.language}" hints="${esc(c.speechHints)}">${say(prompt)}</Gather>`;
const twiml = (inner) => `<?xml version="1.0" encoding="UTF-8"?><Response>${inner}</Response>`;
const greeting = `Thanks for calling ${c.businessName}. I'm the virtual assistant. ` +
  `If you smell gas, have a carbon monoxide alarm going off, or see smoke, say emergency right away. ` +
  `Otherwise, how can I help you today?`;

return [{
  json: {
    ...call,
    twiml: twiml(
      gather(greeting) +
      gather("Sorry, I didn't catch that. How can I help you today?") +
      say(`I didn't hear anything, so I'll end the call. Please call ${c.businessName} back anytime. Goodbye.`) +
      '<Hangup/>'
    ),
  },
}];

const call = $input.first().json;
return [{
  json: {
    ...call,
    decision: {
      action: 'emergency',
      reply: '',
      intent: 'emergency',
      customer_name: '',
      summary: `Emergency detected (${call.emergencyType}). Caller said: "${call.speech}"`,
      callback_needed: true,
    },
  },
}];

const call = $('Config & Parse Call').first().json;
const raw = $input.first().json;
let out = raw.output;

if (typeof out === 'string') {
  try {
    out = JSON.parse(out.replace(/```(json)?/g, '').trim());
  } catch (e) {
    out = { action: 'continue', reply: out };
  }
}

// AI failed or timed out: never leave the caller in silence, hand them to a person.
if (!out || typeof out !== 'object' || raw.error) {
  out = {
    action: 'transfer',
    reply: "I'm sorry, I'm having a little trouble on my end. Let me connect you with someone from our team.",
    intent: 'system_error',
    summary: 'AI error: ' + (raw.error?.message || raw.error || 'no output'),
    callback_needed: true,
  };
}

const allowed = ['continue', 'transfer', 'end', 'emergency'];
let action = String(out.action || 'continue').toLowerCase().trim();
if (!allowed.includes(action)) action = 'continue';

const decision = {
  action,
  reply: String(out.reply || '').trim(),
  intent: String(out.intent || 'other'),
  customer_name: String(out.customer_name || ''),
  summary: String(out.summary || ''),
  callback_needed: out.callback_needed === true || out.callback_needed === 'true',
  transfer_to: String(out.transfer_to || '').toLowerCase().trim(),
};
if (action === 'continue' && !decision.reply) decision.reply = 'Sorry, could you say that one more time?';

return [{ json: { ...call, decision } }];

const item = $input.first().json;
const c = item.config;
const d = item.decision;
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
const say = (t) => `<Say voice="${c.voice}" language="${c.language}">${esc(t)}</Say>`;
// Relative URLs are resolved by Twilio against this webhook's URL.
const gather = (prompt) =>
  `<Gather input="speech" action="hvac-voice?stage=turn" method="POST" speechTimeout="auto" ` +
  `speechModel="phone_call" language="${c.language}" hints="${esc(c.speechHints)}">${say(prompt)}</Gather>`;
const twiml = (inner) => `<?xml version="1.0" encoding="UTF-8"?><Response>${inner}</Response>`;
// Staff phone hears a short "whisper" (hvac-voice?stage=whisper) before the caller is connected.
const numbers = (list, whisper) => list.map((n) => {
  const url = c.whisperToStaff && whisper
    ? ` url="${esc('hvac-voice?stage=whisper&msg=' + encodeURIComponent(whisper.slice(0, 300)))}" method="POST"`
    : '';
  return `<Number${url}>${esc(n)}</Number>`;
}).join('');
const deptKey = c.departments[d.transfer_to] ? d.transfer_to : c.defaultDepartment;
const dept = c.departments[deptKey];
const who = d.customer_name ? `${d.customer_name} (${item.from})` : item.from;
const spokenWho = d.customer_name || 'a customer';

const SAFETY =
  'For your safety: if you smell gas, leave the building now. Do not use light switches, ' +
  'appliances, or open flames, and call 911 or your gas company once you are outside. ' +
  'If a carbon monoxide alarm is sounding, get everyone into fresh air and call 911.';

let inner = '';
let outcome = 'In conversation';
switch (d.action) {
  case 'emergency':
    inner = say(SAFETY) +
      say('I am connecting you to our emergency technician now. Please stay on the line.') +
      `<Dial timeout="30" action="hvac-voice?stage=dial&amp;reason=emergency" method="POST">${numbers(c.emergencyNumbers, `Emergency call from ${spokenWho}. ${item.emergencyType || ''}. Caller said: ${item.speech}`)}</Dial>`;
    outcome = 'EMERGENCY - transferred to on-call';
    break;
  case 'transfer':
    inner = say(d.reply || 'Let me connect you with a member of our team. One moment please.') +
      `<Dial timeout="25" action="hvac-voice?stage=dial&amp;reason=${esc(deptKey)}" method="POST">` +
      `${numbers(dept.numbers, `AI receptionist transfer for ${deptKey}. Caller ${spokenWho}. ${d.summary}`)}</Dial>`;
    outcome = `Transferred to ${deptKey}`;
    break;
  case 'end':
    inner = say(d.reply || `Thanks for calling ${c.businessName}. Have a great day. Goodbye.`) + '<Hangup/>';
    outcome = 'Completed by AI';
    break;
  default:
    inner = gather(d.reply) +
      gather('Are you still there? How else can I help?') +
      say(`I didn't hear anything, so I'll end the call. Please call ${c.businessName} back anytime. Goodbye.`) +
      '<Hangup/>';
}

// Staff SMS text
let notifyStaff = false;
let smsText = '';
if (d.action === 'emergency') {
  notifyStaff = true;
  smsText = `EMERGENCY call from ${who}. Type: ${item.emergencyType || 'reported by caller'}. ` +
    `Caller said: "${item.speech}". Connecting to on-call now.`;
} else if (d.action === 'transfer') {
  notifyStaff = true;
  smsText = `Transfer to ${deptKey}: ${who} is being connected now. ${d.summary}`;
} else if (d.action === 'end' && (c.smsEveryCallSummary || d.callback_needed)) {
  notifyStaff = true;
  smsText = `Call finished: ${who}. ${d.summary}` + (d.callback_needed ? ' CALLBACK NEEDED.' : '');
}

return [{
  json: {
    ...item,
    twiml: twiml(inner),
    outcome,
    notifyStaff,
    smsText: smsText.slice(0, 600),
  },
}];

const call = $input.first().json;
const c = call.config;
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&apos;');
const say = (t) => `<Say voice="${c.voice}" language="${c.language}">${esc(t)}</Say>`;
// Relative URLs are resolved by Twilio against this webhook's URL.
const gather = (prompt) =>
  `<Gather input="speech" action="hvac-voice?stage=turn" method="POST" speechTimeout="auto" ` +
  `speechModel="phone_call" language="${c.language}" hints="${esc(c.speechHints)}">${say(prompt)}</Gather>`;
const twiml = (inner) => `<?xml version="1.0" encoding="UTF-8"?><Response>${inner}</Response>`;
const answered = call.dialStatus === 'completed' || call.dialStatus === 'answered';
const isEmergency = call.reason === 'emergency';

let inner;
if (answered) {
  inner = '<Hangup/>';
} else if (isEmergency) {
  inner = say(
    `I couldn't reach our on-call technician, but they have been alerted and will call you back within ${c.callbackMinutes} minutes. ` +
    'If anyone is in danger, hang up and call 911 now. Goodbye.') + '<Hangup/>';
} else {
  inner = say(
    `Sorry, our team couldn't pick up right now. I've sent them your number and someone will call you back within ${c.callbackMinutes} minutes. ` +
    `Thanks for calling ${c.businessName}. Goodbye.`) + '<Hangup/>';
}

return [{
  json: {
    ...call,
    twiml: twiml(inner),
    missed: !answered,
    smsText: `MISSED ${isEmergency ? 'EMERGENCY ' : ''}transfer from ${call.from} (status: ${call.dialStatus || 'unknown'}). ` +
      `Please call back within ${c.callbackMinutes} minutes.`,
  },
}];

const call = $input.first().json;
const c = call.config;
const msg = String($('Twilio Voice Webhook').first().json.query?.msg || 'Incoming transfer from the AI receptionist.');
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { twiml: `<?xml version="1.0" encoding="UTF-8"?><Response><Say voice="${c.voice}" language="${c.language}">${esc(msg)}. Connecting you now.</Say></Response>` } }];
